import os, time, threading, requests, base64, json
from flask import Flask, Response
from datetime import datetime

TELEGRAM_TOKEN = os.getenv("TELEGRAM_TOKEN") or os.getenv("BOT_TOKEN")
TELEGRAM_CHAT_ID = os.getenv("TELEGRAM_CHAT_ID") or os.getenv("CHAT_ID")
SYMBOLS = ["BTCEUR", "ETHEUR", "SOLEUR", "BNBEUR"]
ICON_B64 = ""
HTML_B64 = ""

app = Flask(__name__)
LOGS = []
bot_thread = None

def log_msg(msg):
    t = datetime.now().strftime("%H:%M:%S")
    entry = f"[{t}] {msg}"
    print(entry, flush=True)
    LOGS.append(entry)
    if len(LOGS) > 300:
        LOGS.pop(0)

def send_telegram(text):
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        return
    try:
        url = f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage"
        requests.post(url, data={"chat_id": TELEGRAM_CHAT_ID, "text": text}, timeout=10)
    except Exception as e:
        log_msg(f"TG error: {e}")

def get_klines(symbol, interval_str, limit=21):
    urls = [
        f"https://data-api.binance.vision/api/v3/klines?symbol={symbol}&interval={interval_str}&limit={limit}",
        f"https://api1.binance.com/api/v3/klines?symbol={symbol}&interval={interval_str}&limit={limit}"
    ]
    for url in urls:
        try:
            r = requests.get(url, timeout=10).json()
            if isinstance(r, list) and len(r) >= 5:
                return r
        except:
            continue
    return []

def get_volume_info(symbol, interval=1, lookback=20):
    try:
        klines = get_klines(symbol, f"{interval}m", lookback+1)
        if not klines:
            return 0, 0, "VOL NORMALE"
        volumes = [float(c[5]) for c in klines]
        vol_now = volumes[-1]
        vol_avg = sum(volumes[:-1]) / len(volumes[:-1]) if len(volumes) > 1 else vol_now
        if vol_avg == 0:
            return vol_now, vol_avg, "VOL NORMALE"
        if vol_now < vol_avg * 0.7:
            label = "VOL BASSO"
        elif vol_now > vol_avg * 1.9:
            label = "VOL ALTO"
        else:
            label = "VOL NORMALE"
        return vol_now, vol_avg, label
    except:
        return 0, 0, "VOL NORMALE"

def get_price_info(symbol):
    try:
        url = f"https://data-api.binance.vision/api/v3/ticker/24hr?symbol={symbol}"
        d = requests.get(url, timeout=10).json()
        return float(d['lastPrice']), float(d['priceChangePercent'])
    except:
        return 0, 0

def loop_bot():
    log_msg("Bot KRAKEN ULTIMATE V2 partito")
    send_telegram("Bot ULTIMATE V2 partito - candele + zoom + storico + notifiche + tema")
    while True:
        try:
            for s in SYMBOLS:
                try:
                    price, change = get_price_info(s)
                    v1, a1, l1 = get_volume_info(s, 1, 20)
                    v5, a5, l5 = get_volume_info(s, 5, 20)
                    log_msg(f"AGG 1m - {s}: {price:.2f}EUR ({change:+.2f}%) | {l1}")
                    now = datetime.now().strftime("%H:%M:%S")
                    msg = "AGG 1m - " + now + "\n" + s + f": {price:.2f}EUR ({change:+.2f}%)\n1m: {l1} ({v1:.1f} vs {a1:.1f})\n5m: {l5} ({v5:.1f} vs {a5:.1f})"
                    send_telegram(msg)
                except Exception as e:
                    log_msg(f"Errore {s}: {e}")
                    continue
            time.sleep(60)
        except Exception as e:
            log_msg(f"Loop error: {e}")
            time.sleep(10)

@app.route("/")
def home():
    global bot_thread
    if bot_thread is None or not bot_thread.is_alive():
        bot_thread = threading.Thread(target=loop_bot, daemon=True)
        bot_thread.start()
        return "Bot ULTIMATE V2 - <a href='/app'>APP CANDELE</a>", 200
    return f"Bot vivo ULTIMATE V2 - {len(LOGS)} log - <a href='/app'>APP</a>", 200

@app.route("/log")
def show_log():
    return "<br>".join(LOGS[-200:])

@app.route("/icon.png")
def icon_png():
    data = base64.b64decode(ICON_B64)
    return Response(data, mimetype="image/png")

@app.route("/manifest.json")
def manifest():
    m = {
        "name": "Crypto Vendi ULTIMATE Candele",
        "short_name": "Vendi ULT",
        "description": "Candele zoom, storico, notifiche, tema, in EURO",
        "start_url": "/app",
        "display": "standalone",
        "background_color": "#070b18",
        "theme_color": "#7c3aed",
        "orientation": "portrait",
        "icons": [
            {"src": "/icon.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"},
            {"src": "/icon.png", "sizes": "192x192", "type": "image/png"}
        ]
    }
    return Response(json.dumps(m, indent=2), mimetype="application/json")

@app.route("/sw.js")
def sw():
    sw_code = """
const CACHE='vendi-ultimate-v2';
self.addEventListener('install', e=>{
 e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/app','/icon.png','/manifest.json'])));
 self.skipWaiting();
});
self.addEventListener('activate', e=>{ e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', e=>{
 e.respondWith(caches.match(e.request).then(r=> r || fetch(e.request).catch(()=>caches.match('/app'))));
});
self.addEventListener('push', e=>{
 const data=e.data ? e.data.json() : {title:'Crypto Vendi',body:'Nuovo segnale!'};
 e.waitUntil(self.registration.showNotification(data.title,{body:data.body,icon:'/icon.png',badge:'/icon.png',vibrate:[200,100,200]}));
});
self.addEventListener('notificationclick', e=>{
 e.notification.close();
 e.waitUntil(clients.openWindow('/app'));
});
"""
    return Response(sw_code, mimetype="application/javascript")

@app.route("/app")
def serve_app():
    html = base64.b64decode(HTML_B64).decode()
    return Response(html, mimetype="text/html")

bot_thread = threading.Thread(target=loop_bot, daemon=True)
bot_thread.start()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 10000)))
